-- Paket 13.11.2026 (4): bottom bar on phones (new chunk HtsBottomBar, call appended to chunk Footers). Text is hex-encoded on purpose.
SET NAMES utf8mb4;
SET SESSION group_concat_max_len = 100000;
-- APPLY. Saves chunk Footers to hts_bak_20261113_bb first; safe to run twice.
CREATE TABLE IF NOT EXISTS hts_bak_20261113_bb (kind VARCHAR(16) NOT NULL, el_id INT NOT NULL, body MEDIUMTEXT, saved_at DATETIME NOT NULL, PRIMARY KEY (kind, el_id)) DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO hts_bak_20261113_bb (kind, el_id, body, saved_at) SELECT 'chunk', c.id, c.snippet, NOW() FROM modx_site_htmlsnippets c WHERE c.name = 'Footers' AND c.snippet NOT LIKE '%[[$HtsBottomBar]]%';
UPDATE modx_site_htmlsnippets c SET c.snippet = CONCAT(CONVERT(c.snippet USING utf8mb4), _utf8mb4 0x0A5B5B24487473426F74746F6D4261725D5D) WHERE c.name = 'Footers' AND c.snippet NOT LIKE '%[[$HtsBottomBar]]%' AND (SELECT COUNT(*) FROM (SELECT id FROM modx_site_htmlsnippets WHERE name = 'Footers') z) = 1;
INSERT INTO modx_site_htmlsnippets (source, name, description, category, snippet, properties, static, static_file)
SELECT 1, 'HtsBottomBar', _utf8mb4 0xD09DD0B8D0B6D0BDD18FD18F20D0BFD0B0D0BDD0B5D0BBD18C20D0BDD0B020D182D0B5D0BBD0B5D184D0BED0BDD0B53A20D0BAD0B0D182D0B0D0BBD0BED0B32C20D0BFD0BED0B8D181D0BA2C20D0BAD0BED180D0B7D0B8D0BDD0B02C20D0BAD0B0D0B1D0B8D0BDD0B5D1822C20D0B7D0B2D0BED0BDD0BED0BA, 0, _utf8mb4 , 'a:0:{}', 0, '' FROM (SELECT 1 AS x) d
WHERE NOT EXISTS (SELECT 1 FROM modx_site_htmlsnippets WHERE name = 'HtsBottomBar');
SELECT itog, COUNT(*) AS n, GROUP_CONCAT(chto ORDER BY chto SEPARATOR '; ') AS what FROM (
SELECT _utf8mb4 0x312E20D09ED0B1D189D0B8D0B920D0BFD0BED0B4D0B2D0B0D0BB20D181D0B0D0B9D182D0B02028D187D0B0D0BDD0BA20466F6F7465727329 AS chto, CASE WHEN (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'Footers') <> 1 THEN _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 WHEN (SELECT snippet FROM modx_site_htmlsnippets WHERE name = 'Footers') LIKE '%[[$HtsBottomBar]]%' THEN _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E ELSE _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C END AS itog
UNION ALL
SELECT _utf8mb4 0x322E20D09DD0BED0B2D18BD0B920D187D0B0D0BDD0BA20487473426F74746F6D426172, CASE WHEN (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'HtsBottomBar') = 0 THEN _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C ELSE _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E END
) q GROUP BY itog;
